import hmac, hashlib, json, base64

SECRET = load_secret("PREFS_HMAC_KEY")

def dump_prefs(prefs: dict) -> str:
    body = base64.urlsafe_b64encode(json.dumps(prefs).encode())
    mac = hmac.new(SECRET, body, hashlib.sha256).hexdigest().encode()
    return (body + b"." + mac).decode()

def load_prefs(cookie: str) -> dict:
    body, _, mac = cookie.encode().partition(b".")
    expected = hmac.new(SECRET, body, hashlib.sha256).hexdigest().encode()
    if not hmac.compare_digest(mac, expected):
        raise ValueError("tampered")
    return json.loads(base64.urlsafe_b64decode(body))      # solo datos, validados después

