def test_tampered_cookie_is_rejected():
    cookie = dump_prefs({"theme": "dark"})
    body, mac = cookie.split(".")
    forged = base64.urlsafe_b64encode(b'{"theme":"dark","role":"admin"}').decode() + "." + mac
    with pytest.raises(ValueError):
        load_prefs(forged)

def test_pickle_payload_is_not_executed(tmp_path):
    marker = tmp_path / "pwned"
    class Evil:
        def __reduce__(self):
            return (open, (str(marker), "w"))
    payload = base64.b64encode(pickle.dumps(Evil())).decode()
    with pytest.raises(Exception):
        load_prefs(payload)
    assert not marker.exists()
